WHERE B.BBS_ID = #{boardId}
	AND (B.BBS_ID = 'LRNSUP' OR M.BBS_ID IS NOT NULL)
	AND B.USE_YN = 'Y'
	AND (B.PSTG_YMD IS NULL OR B.PSTG_YMD = '' OR B.PSTG_YMD <= DATE_FORMAT(CURRENT_DATE, '%Y-%m-%d'))

	AND B.ETC3 = #{programType}




			AND B.ETC1 = #{category}


			AND B.CTGR_CD = #{category}






			AND B.PST_TTL LIKE CONCAT('%', #{keyword}, '%')


			AND B.PST_CN LIKE CONCAT('%', #{keyword}, '%')


			AND (B.PST_TTL LIKE CONCAT('%', #{keyword}, '%') OR B.PST_CN LIKE CONCAT('%', #{keyword}, '%'))

